/* Explicit SI models with bounded inputs and assumptions; no simulation claims. */
const StudioEngineering=(()=>{
 const positive=(n,name,max=1e12)=>{if(typeof n!=='number'||!Number.isFinite(n)||n<1e-9||n>max)throw Error(name+' must be positive and at most '+max);return n;};
 function beam({lengthMm,widthMm,heightMm,forceN,modulusGPa,yieldMPa}){[lengthMm,widthMm,heightMm].forEach(n=>positive(n,'Dimension mm',100000));positive(forceN,'Load N',1e8);positive(modulusGPa,'Modulus GPa',2000);positive(yieldMPa,'Yield MPa',100000);const L=lengthMm/1000,b=widthMm/1000,h=heightMm/1000,I=b*h**3/12,stress=forceN*L*h/2/I/1e6,deflection=forceN*L**3/(3*modulusGPa*1e9*I)*1000;return {bendingStressMPa:stress,tipDeflectionMm:deflection,yieldSafetyFactor:yieldMPa/stress,smallDeflection: deflection<lengthMm/20};}
 function shaft({torqueNm,diameterMm,rpm,efficiency}){positive(torqueNm,'Torque Nm',1e8);positive(diameterMm,'Diameter mm',10000);positive(rpm,'RPM',1000000);positive(efficiency,'Efficiency',1);return {shearStressMPa:16*torqueNm/(Math.PI*(diameterMm/1000)**3)/1e6,mechanicalPowerW:torqueNm*rpm*Math.PI/30,inputPowerW:torqueNm*rpm*Math.PI/30/efficiency};}
 function drone({massKg,motors,thrustRatio,batteryWh,powerW,usableFraction}){positive(massKg,'Mass kg',10000);if(!Number.isInteger(motors)||motors<2||motors>16)throw Error('Use 2–16 motors.');positive(thrustRatio,'Thrust ratio',10);positive(batteryWh,'Battery Wh',100000);positive(powerW,'Average electrical power W',1e7);positive(usableFraction,'Usable energy fraction',1);return {hoverThrustPerMotorN:massKg*9.80665/motors,targetThrustPerMotorN:massKg*9.80665*thrustRatio/motors,estimatedMinutes:batteryWh*usableFraction/powerW*60};}

 function finite(n,name,min=-1e8,max=1e8){if(typeof n!=='number'||!Number.isFinite(n)||n<min||n>max)throw Error(name+' is outside its supported range.');return n;}
 function supportedBeam({lengthMm,widthMm,heightMm,totalLoadN,modulusGPa,yieldMPa}){[lengthMm,widthMm,heightMm].forEach(n=>positive(n,'Dimension mm',100000));positive(totalLoadN,'Load N',1e8);positive(modulusGPa,'Modulus GPa',2000);positive(yieldMPa,'Yield MPa',100000);const L=lengthMm/1000,b=widthMm/1000,h=heightMm/1000,I=b*h**3/12,stress=totalLoadN*L/8*h/2/I/1e6,deflection=5*totalLoadN*L**3/(384*modulusGPa*1e9*I)*1000;return {bendingStressMPa:stress,midspanDeflectionMm:deflection,yieldSafetyFactor:yieldMPa/stress,smallDeflection:deflection<lengthMm/20};}
 function fatigue({minimumMPa,maximumMPa,enduranceMPa,ultimateMPa,yieldMPa}){finite(minimumMPa,'Minimum stress',-100000,100000);finite(maximumMPa,'Maximum stress',-100000,100000);[enduranceMPa,ultimateMPa,yieldMPa].forEach(n=>positive(n,'Strength MPa',100000));if(maximumMPa<=minimumMPa||enduranceMPa>ultimateMPa||yieldMPa>ultimateMPa)throw Error('Use max > min, and endurance/yield strengths no greater than ultimate.');const mean=(maximumMPa+minimumMPa)/2,alternating=(maximumMPa-minimumMPa)/2;return {meanStressMPa:mean,alternatingStressMPa:alternating,modifiedGoodmanSafetyFactor:1/(alternating/enduranceMPa+Math.max(mean,0)/ultimateMPa),peakYieldSafetyFactor:yieldMPa/Math.max(Math.abs(minimumMPa),Math.abs(maximumMPa)),compressiveMeanBenefitIgnored:mean<0};}
 function thermal({powerW,thicknessMm,areaMm2,conductivityWmK,convectionWm2K,ambientC}){positive(powerW,'Heat W',1e8);positive(thicknessMm,'Thickness mm',100000);positive(areaMm2,'Area mm²',1e12);positive(conductivityWmK,'Conductivity W/mK',100000);positive(convectionWm2K,'Convection W/m²K',1e6);finite(ambientC,'Ambient °C',-273.14,10000);const conduction=thicknessMm/1000/(conductivityWmK*areaMm2/1e6),convection=1/(convectionWm2K*areaMm2/1e6);return {conductionResistanceKW:conduction,convectionResistanceKW:convection,totalResistanceKW:conduction+convection,hotFaceTemperatureC:ambientC+powerW*(conduction+convection),outerFaceTemperatureC:ambientC+powerW*convection};}
 function rc({resistanceOhm,capacitanceUf,inputV,frequencyHz,timeMs}){positive(resistanceOhm,'Resistance Ω',1e12);positive(capacitanceUf,'Capacitance µF',1e9);positive(frequencyHz,'Frequency Hz',1e12);finite(inputV,'Input voltage',-100000,100000);finite(timeMs,'Time ms',0,1e12);const tau=resistanceOhm*capacitanceUf/1e6,w=2*Math.PI*frequencyHz*tau,cutoff=1/(2*Math.PI*tau);return {timeConstantMs:tau*1000,cutoffHz:cutoff,gain:1/Math.hypot(1,w),phaseDegrees:-Math.atan(w)*180/Math.PI,stepOutputV:inputV*(1-Math.exp(-timeMs/1000/tau)),series:Array.from({length:81},(_,i)=>{const ratio=10**(-2+i/20);return {x:Math.log10(ratio),y:20*Math.log10(1/Math.hypot(1,ratio))};})};}
 function flight({massKg,motors,rotorDiameterMm,airDensityKgM3,totalThrustN,tiltDegrees,durationS,initialAltitudeM,initialVelocityMs}){positive(massKg,'Mass kg',10000);if(!Number.isInteger(motors)||motors<2||motors>16)throw Error('Use 2–16 motors.');positive(rotorDiameterMm,'Rotor diameter mm',10000);positive(airDensityKgM3,'Air density',10);finite(totalThrustN,'Thrust N',0,1e7);finite(tiltDegrees,'Tilt °',0,80);finite(durationS,'Duration s',0,600);finite(initialAltitudeM,'Altitude m',0,10000);finite(initialVelocityMs,'Vertical speed m/s',-1000,1000);const g=9.80665,angle=tiltDegrees*Math.PI/180,az=totalThrustN*Math.cos(angle)/massKg-g,ax=totalThrustN*Math.sin(angle)/massKg,altitude=initialAltitudeM+initialVelocityMs*durationS+.5*az*durationS**2,area=motors*Math.PI*(rotorDiameterMm/2000)**2;
  let impactTimeS=null;if(az<0){const root=(-initialVelocityMs-Math.sqrt(initialVelocityMs**2+2*(-az)*initialAltitudeM))/az;if(root>=0&&root<=durationS)impactTimeS=root;}else if(initialVelocityMs<0){if(Math.abs(az)<1e-12){const root=-initialAltitudeM/initialVelocityMs;if(root<=durationS)impactTimeS=root;}else{const d=initialVelocityMs**2-2*az*initialAltitudeM;if(d>=0){const root=(-initialVelocityMs-Math.sqrt(d))/az;if(root>=0&&root<=durationS)impactTimeS=root;}}}
  return {verticalAccelerationMs2:az,horizontalAccelerationMs2:ax,predictedAltitudeM:altitude,predictedVerticalVelocityMs:initialVelocityMs+az*durationS,horizontalDisplacementM:.5*ax*durationS**2,groundImpactWithinInterval:impactTimeS!==null,impactTimeS,idealHoverInducedPowerW:(massKg*g)**1.5/Math.sqrt(2*airDensityKgM3*area)};}
 const definitions={
 beam:{label:'Cantilever · rectangular beam · tip load',fields:[['lengthMm','Length mm',200],['widthMm','Width mm',20],['heightMm','Height mm',10],['forceN','Tip load N',100],['modulusGPa','Elastic modulus GPa',69],['yieldMPa','Assumed yield MPa',240]],run:beam,assumptions:'Linear elastic Euler–Bernoulli cantilever, rectangular section, static tip load. Excludes shear deformation, buckling, fatigue and stress concentrations.'},
 supportedBeam:{label:'Simply supported beam · uniform load',fields:[['lengthMm','Span mm',1000],['widthMm','Width mm',50],['heightMm','Height mm',50],['totalLoadN','Total uniformly distributed load N',1000],['modulusGPa','Elastic modulus GPa',200],['yieldMPa','Assumed yield MPa',250]],run:supportedBeam,assumptions:'Prismatic rectangular Euler–Bernoulli beam with simple end supports and uniform static load. Self-weight excluded unless included in total load; no buckling, shear or joint compliance.'},
 shaft:{label:'Solid circular shaft · torque & power',fields:[['torqueNm','Torque N·m',2],['diameterMm','Diameter mm',10],['rpm','Speed RPM',1200],['efficiency','Efficiency 0–1',.8]],run:shaft,assumptions:'Solid circular shaft under pure torsion; no bending, keyways, fatigue or losses beyond the entered efficiency.'},
 drone:{label:'Drone · thrust & energy budget',fields:[['massKg','Mass kg',1.2],['motors','Motor count',4],['thrustRatio','Target thrust / weight',2],['batteryWh','Battery energy Wh',22.2],['powerW','Assumed average draw W',180],['usableFraction','Usable energy 0–1',.8]],run:drone,assumptions:'Static equal thrust and constant electrical draw. Excludes battery sag, flight dynamics, propeller performance and reserves beyond the usable fraction.'},
 fatigue:{label:'Fatigue · modified Goodman screen',fields:[['minimumMPa','Minimum signed stress MPa',-40],['maximumMPa','Maximum signed stress MPa',100],['enduranceMPa','Corrected fatigue strength at chosen life MPa',120],['ultimateMPa','Ultimate tensile strength MPa',500],['yieldMPa','Yield strength MPa',300]],run:fatigue,assumptions:'Uniaxial constant-amplitude stress, modified Goodman relation. Enter fatigue strength already corrected for target life, finish, size, temperature and reliability. Compressive mean benefit ignored. No life prediction, load spectrum, Miner damage or multiaxial correction.'},
 thermal:{label:'Thermal · plane-wall conduction + convection',fields:[['powerW','Heat flow W',10],['thicknessMm','Wall thickness mm',5],['areaMm2','Heat transfer area mm²',10000],['conductivityWmK','Conductivity W/(m·K)',200],['convectionWm2K','Convection h W/(m²·K)',10],['ambientC','Ambient temperature °C',25]],run:thermal,assumptions:'Steady 1D conduction through a uniform wall, followed by convection across the same area. Constant properties. No radiation, lateral heat spreading, contacts, internal generation distribution or transient solution.'},
 rc:{label:'Circuit · passive RC low-pass & step response',fields:[['resistanceOhm','Resistance Ω',1000],['capacitanceUf','Capacitance µF',1],['inputV','Step / signal input V',5],['frequencyHz','Signal frequency Hz',159.154943],['timeMs','Time after zero-state step ms',1]],run:rc,assumptions:'Ideal first-order series RC, output across capacitor, zero initial charge, zero source impedance and infinite load impedance. No parasitics, component tolerances, voltage ratings or nonlinear devices.'},
 flight:{label:'Flight · constant-thrust point-mass motion',fields:[['massKg','Mass kg',1],['motors','Rotor count',4],['rotorDiameterMm','Rotor diameter mm',127],['airDensityKgM3','Air density kg/m³',1.225],['totalThrustN','Total constant thrust N',9.80665],['tiltDegrees','Constant tilt from vertical °',0],['durationS','Prediction duration s',1],['initialAltitudeM','Initial altitude m',2],['initialVelocityMs','Initial vertical velocity m/s',0]],run:flight,assumptions:'Constant mass, thrust and tilt; uniform gravity, no drag or controller. Horizontal initial speed is zero. Ground impact flags invalidate later free-flight predictions. Ideal induced hover power uses independent non-overlapping actuator disks and is a lower bound; no propeller/motor losses, six-DOF dynamics or flight-safety conclusion.'}
 };
 function calculate(model,input){if(!definitions[model])throw Error('Unknown calculation model.');const result=definitions[model].run(input);const check=v=>v===null||typeof v==='boolean'||typeof v==='number'&&Number.isFinite(v)||Array.isArray(v)&&v.every(check)||v&&typeof v==='object'&&Object.values(v).every(check);if(!check(result))throw Error('Inputs produce a non-finite result. Use realistic scales.');return result;}
 function open(){modal('Engineering calculation lab',`<p>Explicit analytical models with assumptions. Enter material and load evidence yourself. Results are independent of the selected mesh and do not establish component or flight safety.</p><label>Model<select id="labModel">${Object.entries(definitions).map(([key,v])=>`<option value="${key}">${v.label}</option>`).join('')}</select></label><div id="labFields"></div><div id="labResult" role="status"></div><p id="labError" role="alert"></p><button type="button" id="labDownload">Export calculation JSON</button><details><summary>Formula references</summary><p><a href="https://ntrs.nasa.gov/api/citations/20230004376/downloads/20230004376.pdf" target="_blank" rel="noopener">NASA · modified Goodman fatigue</a> · <a href="https://ocw.mit.edu/courses/2-051-introduction-to-heat-transfer-fall-2015/e32f70f7e00f34953447b606cea0421f_MIT2_051F15_EqnSheet_Q2_v3.pdf" target="_blank" rel="noopener">MIT · thermal resistance</a> · <a href="https://wiki.analog.com/university/courses/engineering_discovery/lab_5" target="_blank" rel="noopener">Analog Devices · RC filters</a> · <a href="https://ntrs.nasa.gov/api/citations/20160012474/downloads/20160012474.pdf" target="_blank" rel="noopener">NASA · rotor momentum theory</a></p></details>`,()=>false);
 document.getElementById('dialog').classList.add('toolsDialog');document.getElementById('dialog').addEventListener('close',()=>document.getElementById('dialog').classList.remove('toolsDialog'),{once:true});
 let result=null;const select=document.getElementById('labModel'),fields=document.getElementById('labFields'),error=document.getElementById('labError'),output=document.getElementById('labResult');const render=()=>{fields.innerHTML=definitions[select.value].fields.map(([id,label,value])=>`<label>${label}<input type="number" id="lab_${id}" value="${value}" step="any" required></label>`).join('');result=null;output.textContent='';error.textContent='';};render();select.onchange=render;
 document.querySelector('#modalForm>button[type=submit]').textContent='Calculate';document.getElementById('modalForm').onsubmit=e=>{e.preventDefault();try{const definition=definitions[select.value],input=Object.fromEntries(definition.fields.map(([id])=>[id,Number(document.getElementById('lab_'+id).value)]));result={model:select.value,inputs:input,results:calculate(select.value,input),assumptions:definition.assumptions,certified:false};output.innerHTML=Object.entries(result.results).filter(([k])=>k!=='series').map(([k,v])=>`<p><b>${esc(k)}</b>: ${typeof v==='number'?v.toPrecision(6):v===null?'None':v}</p>`).join('')+'<p>'+esc(result.assumptions)+'</p>';if(result.results.series){const points=result.results.series.map(p=>(40+(p.x+2)*110)+','+(20-p.y*4)).join(' ');output.innerHTML+=`<svg viewBox="0 0 520 225" role="img" aria-label="Ideal RC low-pass gain: 0 to minus 40 decibels across frequency ratio 0.01 to 100"><path d="M40 20v160h440" fill="none" stroke="currentColor"/><polyline points="${points}" fill="none" stroke="#adc67e" stroke-width="3"/><text x="40" y="203" fill="currentColor">0.01 × cutoff</text><text x="245" y="203" fill="currentColor">1×</text><text x="410" y="203" fill="currentColor">100×</text><text x="4" y="25" fill="currentColor">0dB</text><text x="0" y="180" fill="currentColor">−40</text></svg>`;}error.textContent='';}catch(e){result=null;error.textContent=e.message;output.textContent='';}};document.getElementById('labDownload').onclick=()=>{if(!result)return toast('Calculate valid inputs first.');download('engineering-calculation.json',JSON.stringify(result,null,2),'application/json');};}
 return {beam,shaft,drone,supportedBeam,fatigue,thermal,rc,flight,calculate,open};
})();
